"""Bind compatibility validation for caches generated by the frozen L1 evaluator."""
import json
from datetime import datetime, timezone
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
import src.mask_semantics_recovery_v2 as recovery

out = ROOT / "outputs/mask_semantics_recovery_v2"
protocol = json.loads((out / "RECOVERY_PROTOCOL.json").read_text(encoding="utf-8"))
amendment2 = json.loads((out / "RECOVERY_PROTOCOL_AMENDMENT_002.json").read_text(encoding="utf-8"))
obj = {
    "amendment_version": "003",
    "amended_utc": datetime.now(timezone.utc).isoformat(),
    "prior_protocol_binding_sha256": protocol["binding_sha256"],
    "prior_amendment_binding_sha256": amendment2["amendment_binding_sha256"],
    "prior_runner_source_sha256": amendment2["runner_source_sha256"],
    "runner_source_sha256": recovery.sha256(Path(recovery.__file__)),
    "reason": "The resumed run correctly rejected prediction caches because their evaluator-source digest belongs to the frozen runner that generated them before the bootstrap-only fix. The caches and manifest hashes are intact; a source-code bookkeeping edit should not invalidate them.",
    "change": "Cache validation accepts the current evaluator digest or the exact evaluator digest frozen in Amendment 001 for already-generated recovery mask predictions. Protocol, checkpoint, preprocessing, record order, mask, schema, dimensions, and prediction checks remain mandatory.",
    "scope": "Cache provenance compatibility only. No prediction content, outcome, estimand, split, bootstrap index, mask meaning, threshold, model, training, or tolerance changed.",
    "existing_mask_inference_preserved": True,
    "point_metrics_completed_before_patch": True,
    "bootstrap_task_path_fix_in_amendment_002_preserved": True,
}
obj["amendment_binding_sha256"] = recovery.hash_json(obj)
(out / "RECOVERY_PROTOCOL_AMENDMENT_003.json").write_text(
    json.dumps(obj, indent=2, sort_keys=True) + "\n", encoding="utf-8"
)
print(obj["amendment_binding_sha256"], obj["runner_source_sha256"])
